resources.string:
"<!DOCTYPE html PUBLIC "-//W3C//DTD HTML 4.01//EN">
<html>
    <head>
        <style type="text/css">

            table {
                width: auto;
            }
            hr {
                border: 0;
                width: 80%;
                background-color: #FFFFFF;
                height: 1px;
            }
            a {
                color: #007CF7;
                text-decoration: none;
            }

            a:link{
                color: #007CF7;
                text-decoration: underline;
            }

            li{
                font-family: __BODY_FONT_NAME__;
                color: __BODY_FONT_COLOR__;
            }

            ul {
                list-style-position: inside;
                padding-left:0px;
            }

            ol {
                padding-left:24px;
            }

            b {
                font-family: __BOLD_FONT_NAME__;
                color: __BOLD_FONT_COLOR__;
            }

            br {
                font-family: __BODY_FONT_NAME__;
                color: #6E6868;
            }

            img {
                display: inline;
                height: auto;
                max-width: 100%;
            }

            body {
                -webkit-text-size-adjust: none;
                font-family: __BODY_FONT_NAME__;
                color: __BOLD_FONT_COLOR__;
                font-family: __BODY_FONT_NAME__;
                font-size: 14px;
                background: transparent;
                word-wrap: break-word;
                padding-left: 0px;
                padding-right: 0px;
                padding-top: 0px;
            }

            embed{
                width:100%;
            }

            object{
                width:100%;

            }

            iframe{
                width:100%;

            }

            html {
                -webkit-text-size-adjust: none; / Never autoresize text /
            }
        </style>
        <meta name='viewport' content='width=device-width, initial-scale=1.0, maximum-scale=1.0'>
    </head>
<body>"
